import React from "react";
import "./LeadKanban.css";

const statuses = [
  { key: "new", label: "Mới" },
  { key: "processing", label: "Đang xử lý" },
  { key: "converted", label: "Chuyển đổi" },
  { key: "lost", label: "Mất" },
];

const LeadKanban = ({ leads, onDragStart, onDrop, onDelete }) => {
  return (
    <div className="kanban-board">
      {statuses.map((status) => (
        <div
          key={status.key}
          className="kanban-column"
          onDragOver={(e) => e.preventDefault()}
          onDrop={() => onDrop(status.key)}
        >
          <h3>{status.label}</h3>
          {leads
            .filter((lead) => lead.status === status.key)
            .map((lead) => (
              <div
                key={lead._id}
                className="kanban-card"
                draggable
                onDragStart={() => onDragStart(lead)}
              >
                <h4>{lead.name}</h4>
                <p>{lead.email}</p>
                <p>{lead.phone}</p>
                <button
                  className="delete-btn"
                  onClick={() => onDelete(lead._id)}
                >
                  ❌
                </button>
              </div>
            ))}
        </div>
      ))}
    </div>
  );
};

export default LeadKanban;
